#define SHAPE_CYCLE 4.5 // how often (seconds) a 'gyroid' variant should morft
#define MORFING_SPEED 4. // how much time (second) morfing should take
#define SHAPES_COUNT 14.
#define TIME_SPEED_FACTOR 1.1
#define PI 3.1415926


float sdSphere(vec3 p, vec3 c, float r) {
