    vec3 ve1 = vec3(p);
    vec3 ve2 = vec3(p);

    //np.z = sin(np.z * 3.) * 1.2;
    //np.y = sin(np.y * 4.) * 1.1;
    //np.y = sin(np.x * 1.) * 1.;
    //np.z = sin(np.z * 2.) * 1.2;



