    int shape = int(mod(mod(iTime / SHAPE_CYCLE, SHAPES_COUNT * SHAPE_CYCLE), SHAPES_COUNT));
    float cycleTime = mod(iTime, SHAPE_CYCLE);

    switch (shape) {
        case 0: ve1.y = sin(np.z * sin(iTime) * 2. + np.y * 0.9) * 1.6; ve2.y = sin(np.y * 3. + np.x * 3.) * 1.3; break;
        case 1: ve1.y = sin(np.y * 3. + np.x * 3.) * 1.3; ve2.y = abs(cos(np.y)) / 2.1  * sin(np.y * 8. + np.x * 8.) * 1.3; break;
        case 2: ve1.y = abs(cos(np.y)) / 2.1  * sin(np.y * 8. + np.x * 8.) * 1.3; ve2.z = atan(np.x * 2. + np.y * 5.) * 1.2; break;
        case 3: ve1.z = atan(np.x * 2. + np.y * 5.) * 1.2; ve2.y = atan(np.z * sin(iTime) * 2. + np.y * 0.9) * 1.6; break;
        case 4: ve1.y = atan(np.z * sin(iTime) * 2. + np.y * 0.9) * 1.6; ve2.y = sin(ve1.x * 2.9) * 1.4; break;
        case 5: ve1.y = sin(ve1.x * 2.9) * 1.4; ve2.z = sin(np.z * 3.) * 1.2; break;
        case 6: ve1.z = sin(np.z * 3.) * 1.2; ve2.z = clamp(sin(np.z * 4.), -0.9, 0.9) * 1.2; break;
        case 7: ve1.z = clamp(sin(np.z * 4.), -0.9, 0.9) * 1.2; ve2.x = clamp(sin(np.y * 4.), -0.3, 0.6) * 1.2;  break;
        case 8: ve1.x = clamp(sin(np.y * 4.), -0.3, 0.6) * 1.2; ve2.z = sin(dot(ve1, ve2)) * 0.4;   break;
        case 9: ve1.z = sin(dot(ve1, ve2)) * 0.4; ve2.z = sin(dot(ve1, ve2)) * 0.4;  break;
